// Only the public game shell is cached. Authentication pages and unrelated requests are excluded.
const CACHE='nightwatch-v2.0.0';
const ASSETS=['./','./index.html','./styles.css','./engine.js','./game.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(async cache=>{for(const path of ASSETS){const response=await fetch(new URL(path,self.registration.scope),{cache:'reload'});if(!response.ok||response.redirected||new URL(response.url).origin!==self.location.origin)throw new Error('Game shell unavailable');await cache.put(new URL(path,self.registration.scope),response);}})));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('nightwatch-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const allowed=ASSETS.map(p=>new URL(p,self.registration.scope).href);if(!allowed.includes(url.href))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&!response.redirected&&new URL(response.url).origin===self.location.origin){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)));}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||Response.error())));});
